// Reference solution
function amdahl(sharePct, speedup) {
  // tiết kiệm = tỉ lệ × (1 − 1/tăng tốc). Xoá hẳn phần đó (tăng tốc vô hạn) ⇒ tiết kiệm đúng bằng tỉ lệ — đó là TRẦN.
  const saving = sharePct * (1 - 1 / speedup);
  return Number(saving.toFixed(2));
}

